const sites = [
  {
    source: 'ICICI Bank',
    product_name: 'Personal Loan',
    url: 'https://www.icici.bank.in/personal-banking/loans/personal-loan/eligibility',
    selector: 'span.step-bullet',
    role: 'primary',
    enabled: true,
  },
  {
    source: 'HDFC Bank',
    product_name: 'Personal Loan',
    url: 'https://www.hdfc.bank.in/personal-loan/eligibility-criteria',
    selector: 'span.description, span.accordion-faq_description, div.accordion-faq_description p',
    role: 'primary',
    enabled: true,
  },
  {
    source: 'IDFC FIRST Bank',
    product_name: 'Personal Loan',
    url: 'https://www.idfcfirst.bank.in/personal-banking/loans/personal-loan',
    selector: 'h1.hd1, li.eligi-hover-content, div.gsa-ir-desc p, div.gfnfnb-desc p.txt',
    role: 'primary',
    enabled: true,
  },
  {
    source: 'BankBazaar',
    product_name: 'Personal Loan',
    url: 'https://www.bankbazaar.com/personal-loan-eligibility.html',
    selector: 'table.w-full tr',
    role: 'spare',
    enabled: false,
  },
];

return sites.filter((site) => site.enabled).map((site) => ({ json: site }));

const CRITERIA_WORDS = /(income|salary|age\b|years|cibil|credit score|score|employ|salaried|self-employed|business|interest|p\.a\.|p\.m|₹|rs\.)/i;
const MONTH_YEAR = /(?:\s+(?:in|on|as of))?\s*\b(?:jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\s*['’]?\s*\d{2,4}\b/gi;
const HAS_NUMBER_OR_PROFILE = /(\d|salaried|self-employed|employee|business)/i;
const BOILERPLATE = /(disclaimer|terms and conditions|click here)/i;
const MIN_LINE_LENGTH = 20;
const MAX_LINE_LENGTH = 400;

function cleanLine(raw) {
  return String(raw)
    .replace(/[\u00a0\u200b]/g, ' ')
    .replace(/\[[^\]]*\]/g, ' ')
    .replace(/[•*]+/g, ' ')
    .replace(MONTH_YEAR, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function criteriaLines(blocks) {
  const lines = blocks
    .map(cleanLine)
    .filter((line) => line.length >= MIN_LINE_LENGTH && line.length <= MAX_LINE_LENGTH)
    .filter((line) => CRITERIA_WORDS.test(line))
    .filter((line) => HAS_NUMBER_OR_PROFILE.test(line))
    .filter((line) => !BOILERPLATE.test(line));
  return [...new Set(lines)].sort();
}

const target = $('Config · Crawl targets').item.json;
const fetched = $('Fetch · Crawl page').item.json;
const lines = criteriaLines($input.item.json.blocks || []);

return {
  json: {
    source: target.source,
    product_name: target.product_name,
    source_url: target.url,
    role: target.role,
    status: lines.length > 0 ? 'ok' : 'no_criteria_found',
    http_status: fetched.statusCode,
    html_bytes: String(fetched.data || '').length,
    line_count: lines.length,
    criteria_lines: lines,
    criteria_text: lines.join('\n'),
    fetched_at: new Date().toISOString(),
  },
};

const MODEL = 'openai/gpt-oss-120b';
const MAX_COMPLETION_TOKENS = 1000;
const EMPLOYMENT_GROUPS = ['Salaried', 'Self-Employed', 'Business'];

const SYSTEM_PROMPT = [
  "You extract one lender's personal-loan eligibility criteria from the text the user sends.",
  '1. Use only what the text states. Never infer, compute or convert. If a value is not stated, return null.',
  '2. min_monthly_income is the lowest net monthly income in rupees as a plain number (₹30,000 -> 30000).',
  '3. Credit scores are on the 300-900 scale. "700 and above" -> min_credit_score 700, even when the text calls it preferred or ideal.',
  '4. Ages are whole years. "between 21 and 60" -> min_age 21, max_age 60.',
  '5. Interest rates are percent per annum. A monthly rate counts only through its stated annual equivalent. If only a starting rate is stated, set interest_rate_min and leave interest_rate_max null.',
  '6. allowed_employment lists only the groups the text names, using exactly Salaried, Self-Employed or Business. Null when the text names none.',
  '7. If thresholds differ by employment type, or the text states conditions these fields cannot express (work experience, business vintage, employer type), use the loosest bound for each field and set has_conditional_criteria to true. Otherwise false.',
].join('\n');

const nullableNumber = { type: ['number', 'null'] };
const nullableInteger = { type: ['integer', 'null'] };

const RESPONSE_SCHEMA = {
  type: 'object',
  properties: {
    min_monthly_income: nullableNumber,
    min_credit_score: nullableInteger,
    max_credit_score: nullableInteger,
    min_age: nullableInteger,
    max_age: nullableInteger,
    interest_rate_min: nullableNumber,
    interest_rate_max: nullableNumber,
    allowed_employment: {
      type: ['array', 'null'],
      items: { type: 'string', enum: EMPLOYMENT_GROUPS },
    },
    has_conditional_criteria: { type: 'boolean' },
  },
  required: [
    'min_monthly_income',
    'min_credit_score',
    'max_credit_score',
    'min_age',
    'max_age',
    'interest_rate_min',
    'interest_rate_max',
    'allowed_employment',
    'has_conditional_criteria',
  ],
  additionalProperties: false,
};

return $input.all().map(({ json }) => ({
  json: {
    source: json.source,
    product_name: json.product_name,
    source_url: json.source_url,
    role: json.role,
    criteria_text: json.criteria_text,
    line_count: json.line_count,
    fetched_at: json.fetched_at,
    llm: {
      purpose: 'crawl_structuring',
      model: MODEL,
      system: SYSTEM_PROMPT,
      user: `Lender: ${json.source}\nProduct: ${json.product_name}\nCriteria text:\n${json.criteria_text}`,
      schema_name: 'loan_product_criteria',
      json_schema: RESPONSE_SCHEMA,
      max_tokens: MAX_COMPLETION_TOKENS,
    },
  },
}));

const EMPLOYMENT_GROUPS = ['Salaried', 'Self-Employed', 'Business'];
const REQUIRED_KEYS = [
  'min_monthly_income',
  'min_credit_score',
  'max_credit_score',
  'min_age',
  'max_age',
  'interest_rate_min',
  'interest_rate_max',
  'allowed_employment',
  'has_conditional_criteria',
];
const LIMITS = {
  income: [1000, 10000000],
  score: [300, 900],
  age: [18, 100],
  rate: [0.01, 100],
};
const CONFIDENCE_WEIGHTS = { income: 0.3, credit: 0.25, age: 0.2, rate: 0.15, employment: 0.1 };
const CONDITIONAL_CONFIDENCE_CAP = 0.6;
const UNIT_MULTIPLIERS = { k: 1e3, lakh: 1e5, lakhs: 1e5, lac: 1e5, crore: 1e7, cr: 1e7 };
const AMOUNT_WORD = /(\d+(?:\.\d+)?)\s*(k|lakhs?|lac|crore|cr)\b/gi;
const PLAIN_NUMBER = /\d[\d,]*(?:\.\d+)?/g;

function coerceNumber(value) {
  if (value === null || value === undefined) return null;
  if (typeof value === 'number') return Number.isFinite(value) ? value : NaN;
  const text = String(value)
    .toLowerCase()
    .replace(/,/g, '')
    .replace(/₹|\brs\b\.?|\binr\b|%/g, ' ')
    .replace(/\/\s*(month|year|mo|yr)|per\s+(month|year)|years?|yrs?|p\.?a\.?|p\.?m\.?/g, ' ')
    .trim();
  const match = text.match(/^(\d+(?:\.\d+)?)\s*(k|lakhs?|lac|crore|cr)?$/);
  if (!match) return NaN;
  return Number(match[1]) * (match[2] ? UNIT_MULTIPLIERS[match[2]] : 1);
}

function numbersInText(text) {
  const found = new Set();
  for (const token of text.match(PLAIN_NUMBER) || []) found.add(Number(token.replace(/,/g, '')));
  for (const [, amount, unit] of text.matchAll(AMOUNT_WORD)) {
    found.add(Number(amount) * UNIT_MULTIPLIERS[unit.toLowerCase()]);
  }
  return found;
}

function checkNumber(errors, name, raw, [low, high], integer) {
  const value = coerceNumber(raw);
  if (value === null) return null;
  if (Number.isNaN(value)) {
    errors.push(`${name} is not a number: ${JSON.stringify(raw)}`);
    return null;
  }
  if (integer && !Number.isInteger(value)) errors.push(`${name} must be a whole number, got ${value}`);
  if (value < low || value > high) errors.push(`${name}=${value} outside ${low}..${high}`);
  return value;
}

function checkOrder(errors, lowName, low, highName, high) {
  if (low !== null && high !== null && low > high) errors.push(`${lowName} ${low} exceeds ${highName} ${high}`);
}

function checkEmployment(errors, raw) {
  if (raw === null) return null;
  if (!Array.isArray(raw) || raw.length === 0) {
    errors.push('allowed_employment must be null or a non-empty list');
    return null;
  }
  const unknown = raw.filter((group) => !EMPLOYMENT_GROUPS.includes(group));
  if (unknown.length > 0) errors.push(`allowed_employment has unknown groups: ${unknown.join(', ')}`);
  return [...new Set(raw)].sort();
}

function checkGrounded(errors, fields, text) {
  const present = numbersInText(text);
  const numeric = [
    'min_monthly_income',
    'min_credit_score',
    'max_credit_score',
    'min_age',
    'max_age',
    'interest_rate_min',
    'interest_rate_max',
  ];
  for (const name of numeric) {
    if (fields[name] !== null && !present.has(fields[name])) {
      errors.push(`${name}=${fields[name]} does not appear in the criteria text`);
    }
  }
}

function parseConfidence(fields) {
  const filled = {
    income: fields.min_monthly_income !== null,
    credit: fields.min_credit_score !== null || fields.max_credit_score !== null,
    age: fields.min_age !== null || fields.max_age !== null,
    rate: fields.interest_rate_min !== null || fields.interest_rate_max !== null,
    employment: fields.allowed_employment !== null,
  };
  const score = Object.keys(filled).reduce((sum, key) => sum + (filled[key] ? CONFIDENCE_WEIGHTS[key] : 0), 0);
  const capped = fields.has_conditional_criteria ? Math.min(score, CONDITIONAL_CONFIDENCE_CAP) : score;
  return Math.round(capped * 100) / 100;
}

function parseModelAnswer(result) {
  const parsed = result.data;
  if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
    return { errors: ['LLM Gateway answer is not a JSON object'], content: JSON.stringify(parsed ?? null) };
  }
  const content = JSON.stringify(parsed);
  const missing = REQUIRED_KEYS.filter((key) => !(key in parsed));
  return missing.length > 0 ? { errors: [`LLM Gateway answer lacks fields: ${missing.join(', ')}`], content } : { parsed, errors: [], content };
}

function structure(result, context) {
  const answer = parseModelAnswer(result);
  const errors = [...answer.errors];
  if (errors.length > 0) return { errors, content: answer.content };
  const raw = answer.parsed;
  const fields = {
    min_monthly_income: checkNumber(errors, 'min_monthly_income', raw.min_monthly_income, LIMITS.income, false),
    min_credit_score: checkNumber(errors, 'min_credit_score', raw.min_credit_score, LIMITS.score, true),
    max_credit_score: checkNumber(errors, 'max_credit_score', raw.max_credit_score, LIMITS.score, true),
    min_age: checkNumber(errors, 'min_age', raw.min_age, LIMITS.age, true),
    max_age: checkNumber(errors, 'max_age', raw.max_age, LIMITS.age, true),
    interest_rate_min: checkNumber(errors, 'interest_rate_min', raw.interest_rate_min, LIMITS.rate, false),
    interest_rate_max: checkNumber(errors, 'interest_rate_max', raw.interest_rate_max, LIMITS.rate, false),
    allowed_employment: checkEmployment(errors, raw.allowed_employment),
    has_conditional_criteria: raw.has_conditional_criteria === true,
  };
  checkOrder(errors, 'min_credit_score', fields.min_credit_score, 'max_credit_score', fields.max_credit_score);
  checkOrder(errors, 'min_age', fields.min_age, 'max_age', fields.max_age);
  checkOrder(errors, 'interest_rate_min', fields.interest_rate_min, 'interest_rate_max', fields.interest_rate_max);
  checkGrounded(errors, fields, context.criteria_text);
  if (parseConfidence(fields) === 0) errors.push('no criteria were extracted');
  return { fields, errors, content: answer.content };
}

const result = $input.item.json;
const context = $('Prompt · Build LLM request').item.json;
const { fields, errors, content } = structure(result, context);

const base = {
  source: context.source,
  product_name: context.product_name,
  source_url: context.source_url,
  fetched_at: context.fetched_at,
  model: result.model,
  prompt_tokens: result.prompt_tokens ?? null,
  completion_tokens: result.completion_tokens ?? null,
  llm_calls: result.attempts ?? 1,
};

if (errors.length > 0) {
  return {
    json: {
      ...base,
      status: 'structuring_invalid',
      error: `Structured output rejected: ${errors.join('; ')}`,
      raw_model_output: String(content ?? '').slice(0, 500),
    },
  };
}

return {
  json: {
    ...base,
    status: 'structured',
    interest_rate_min: fields.interest_rate_min,
    interest_rate_max: fields.interest_rate_max,
    min_monthly_income: fields.min_monthly_income,
    min_credit_score: fields.min_credit_score,
    max_credit_score: fields.max_credit_score,
    min_age: fields.min_age,
    max_age: fields.max_age,
    allowed_employment: fields.allowed_employment,
    has_conditional_criteria: fields.has_conditional_criteria,
    raw_criteria_text: context.criteria_text,
    parse_confidence: parseConfidence(fields),
  },
};

const product = $input.item.json;
const employment = product.allowed_employment;

return {
  json: {
    source: product.source,
    product_name: product.product_name,
    source_url: product.source_url,
    interest_rate_min: product.interest_rate_min,
    interest_rate_max: product.interest_rate_max,
    min_monthly_income: product.min_monthly_income,
    min_credit_score: product.min_credit_score,
    max_credit_score: product.max_credit_score,
    min_age: product.min_age,
    max_age: product.max_age,
    allowed_employment: employment === null ? null : `{${employment.join(',')}}`,
    raw_criteria_text: product.raw_criteria_text,
    parse_confidence: product.parse_confidence,
    llm_calls: product.llm_calls,
  },
};
